function peutModifier(array $session, int $auteurId): bool {
    if (!isset($session['user_id'])) {
        return false;
    }
    return ($session['role'] ?? '') === 'admin' && $session['user_id'] === $auteurId;
}

function validerInscription(string $nom, int $age): array {
    $erreurs = [];
    if (empty(trim($nom))) {
        $erreurs[] = "Le nom est obligatoire.";
    }
    if ($age < 0 && $age > 120) {
        $erreurs[] = "L'âge doit être entre 0 et 120.";
    }
    return $erreurs;
}
